/** 문단이 인용한 원문입니다. quote는 원문 transcript의 부분 문자열이어야 한다(명세 8장 검증). */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="paragraph_sources", indexes=@Index(name="idx_paragraph_sources_paragraph", columnList="paragraphId")) public class ParagraphSource { @Id private String id; @Column(nullable=false) private String paragraphId; @Column(nullable=false) private String entryId; @Column(nullable=false) private String memberId; @Column(nullable=false,length=3000) private String quote; @Column(nullable=false) private int sortOrder; protected ParagraphSource(){} private ParagraphSource(String p,String e,String m,String q,int o){id=UUID.randomUUID().toString();paragraphId=p;entryId=e;memberId=m;quote=q;sortOrder=o;} public static ParagraphSource of(String paragraphId,String entryId,String memberId,String quote,int sortOrder){return new ParagraphSource(paragraphId,entryId,memberId,quote,sortOrder);} public String getParagraphId(){return paragraphId;} public String getEntryId(){return entryId;} public String getMemberId(){return memberId;} public String getQuote(){return quote;} public int getSortOrder(){return sortOrder;} }
